{"code": "import pandas as pd, numpy as np
df = pd.read_csv('data/explore.csv')
expos = ['canopy_cover','soil_moisture','elevation_m','road_dist_km','leaf_litter','temperature_c','slope_deg','nitrate','grazing_index','rainfall_mm']
# within-region correlation with richness
for e in expos:
    cors=[]
    for r,g in df.groupby('region'):
        cors.append(g[e].corr(g['species_richness']))
    print(f"{e:16s} within-region cors: {[round(c,2) for c in cors]}  mean={np.mean(cors): .3f}")
"}
